package com.shazwan.idash;
import android.app.*;import android.content.*;import android.os.*;import android.provider.Settings;import android.view.*;import java.io.*;
/** Official links and denied-access states; does not grant access or change DND. Disposable emulator only. */
public class SettingsAccessChecks extends Instrumentation {
 LauncherActivity a;int count;boolean listener,policy;NotificationManager nm;
 void check(boolean ok,String msg){if(!ok)throw new AssertionError(msg);count++;}
 void ui(Runnable r){Throwable[] error={null};runOnMainSync(()->{try{r.run();}catch(Throwable e){error[0]=e;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
 void shell(String s)throws Exception{try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(s);InputStream in=new FileInputStream(fd.getFileDescriptor())){byte[] b=new byte[2048];while(in.read(b)!=-1){}}}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;try{
  nm=(NotificationManager)getTargetContext().getSystemService(Context.NOTIFICATION_SERVICE);listener=nm.isNotificationListenerAccessGranted(new ComponentName(getTargetContext(),MediaAccessService.class));policy=nm.isNotificationPolicyAccessGranted();int filter=nm.getCurrentInterruptionFilter();
  shell("appops set com.shazwan.idash WRITE_SETTINGS deny");shell("cmd notification disallow_listener com.shazwan.idash/.MediaAccessService");shell("cmd notification disallow_dnd com.shazwan.idash");
  a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ui(()->new DashSettings(a).open("About"));ui(()->{String status=a.settingsScreen.actions.accessStatus();check(status.contains("Kecerahan: akses diperlukan")&&status.contains("Media: akses diperlukan")&&status.contains("DND: akses diperlukan"),"denied states shown honestly");a.settingsScreen.actions.permissions();a.settingsScreen.dialog.getListView().performItemClick(null,2,2);});ui(()->{check(a.settingsScreen.dialog.getButton(AlertDialog.BUTTON_POSITIVE)!=null,"media disclosure exposes explicit access link");a.settingsScreen.dialog.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();check(!nm.isNotificationListenerAccessGranted(new ComponentName(a,MediaAccessService.class)),"Cancel never grants media access");check(nm.getCurrentInterruptionFilter()==filter,"opening Settings never changes DND");});
  ui(()->a.settingsScreen.actions.permissions());runOnMainSync(()->a.settingsScreen.dialog.getListView().performItemClick(null,1,1));long until=SystemClock.elapsedRealtime()+12000;while(a.resumed&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);check(!a.resumed,"brightness access opens real Android Settings");shell("am start -n com.shazwan.idash/.LauncherActivity");until=SystemClock.elapsedRealtime()+12000;while(!a.resumed&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);ui(()->new DashSettings(a).open("About"));ui(()->{check(a.resumed,"return from Android Settings resumes launcher");a.settingsScreen.actions.launch(new Intent().setComponent(new ComponentName("dev.idash.absent","dev.idash.absent.Main")));check(true,"missing external activity handled without crash");});
  result.putString("stream","PASS: "+count+" Settings access/fallback checks\n");code=Activity.RESULT_OK;
 }catch(Throwable e){result.putString("stream","FAIL after "+count+": "+e+"\n");}finally{try{shell("appops set com.shazwan.idash WRITE_SETTINGS default");if(listener)shell("cmd notification allow_listener com.shazwan.idash/.MediaAccessService");if(policy)shell("cmd notification allow_dnd com.shazwan.idash");}catch(Exception ignored){}if(a!=null)ui(a::finish);}finish(code,result);}
}
